22	    // The first angle remains unchanged.
23	    for (int i = 1; i < PULSES; i++) {
24	
25	        // Save the current original value before modifying it.
26	        double current_orig = angles[i];
27	        double diff = current_orig - prev_orig;
28	
29	        // Wrap diff into the range [-pi, pi)
30	        double dp = fmod(diff + PI, TWO_PI);
31	        if (dp < 0)
32	            dp += TWO_PI;
33	        dp -= PI;
34	
35	        // Adjust the edge case: if dp == -pi and diff > 0, set dp to pi.
36	        if (dp == -PI && diff > 0)
37	            dp = PI;
38	
39	        // The new (unwrapped) angle is the previous unwrapped angle plus dp.
40	        angles[i] = angles[i - 1] + dp;
41	
42	        // Update prev_orig to the original value before modification.
43	        prev_orig = current_orig;
44	    }
